typedef struct { int u, v, w; } Edge;
int cmp(const void *a, const void *b) { return ((Edge *)a)->w - ((Edge *)b)->w; }

int kruskal(Edge e[], int E, int V) {
  qsort(e, E, sizeof *e, cmp);
  make_sets(V);
  int total = 0, used = 0;
  for (int i = 0; i < E && used < V - 1; i++)
    if (find(e[i].u) != find(e[i].v)) {
      unite(e[i].u, e[i].v); total += e[i].w; used++;
    }
  return total;
}
